 function act(label,key,action,extra='',kind='blue'){return button(`${icon(key,'action-icon')}<span>${esc(label)}</span>`,action,kind,extra);}
 function left(at,t=now()){const s=Math.max(0,Math.ceil((at-t)/1000));return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s/60)%60).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
