 function personRow(m,add=false){return `<div class="social-person"><button data-action="soc-profile" data-id="${m.id}" ${m.id==='self'?'disabled':''}>${icon(m.badge||'clan-badge','person-badge')}<span><b>${esc(m.name)}</b><small>${esc(m.role||m.tag||'')}${m.online?' · Online':''}</small></span><strong>${icon('trophy')}${fmt(m.trophies)}</strong></button>${add&&m.id!=='self'?button('Add','soc-add-friend','blue',`data-id="${m.id}" ${p().world.friends.includes(m.id)?'disabled':''}`):''}</div>`;}
 function clanRow(c){return `<button class="clan-directory-row" data-action="soc-clan" data-id="${c.id}">${icon(c.badge,'clan-directory-badge')}<span><b>${esc(c.name)}</b><small>${esc(c.type)} · ${c.count}/50 · ${esc(c.region||'')}</small></span><strong>${icon('trophy')}${fmt(c.trophies)}</strong></button>`;}
 function hub(){const profile=p(),cl=W.clan(profile,profile.world.currentClan),friends=profile.world.friends.map(id=>W.player(profile,id)).filter(Boolean).sort((a,b)=>Number(b.online)-Number(a.online)||b.trophies-a.trophies);
  $('clanContent').innerHTML=`<div class="social-hub">${cl?`<section class="social-clan-card">${icon(cl.badge)}<h2>${word(cl.name)}</h2><p>${esc(cl.description||'Welcome to the clan.')}</p><div class="clan-facts"><span>${cl.count}/50 members</span><span>${fmt(cl.trophies)} trophies</span></div><div class="social-actions">${act('Chat','emote-icon','soc-chat')}${act('Members','clan','soc-members')}${act('Clan Wars','event-war','soc-war')}</div></section>`:`<section class="social-clan-card"><h2>${word('Find your clan')}</h2><p>Meet players, exchange cards, and take part in Clan Wars.</p><div class="social-actions">${act('Find Clan','clan','soc-browse')}${act('Create','team-icon','soc-create','','green')}</div></section>`}
  <div class="social-tabs"><button data-action="soc-friends" class="${hubTab==='friends'?'selected':''}">Friends</button><button data-action="soc-browse" class="${hubTab==='browse'?'selected':''}">Clan Search</button></div>
  ${hubTab==='friends'?`<section id="friendsList">${friends.length?friends.map(m=>personRow(m)).join(''):'<div class="social-empty"><h3>No friends added yet</h3><p>Open a clanmate’s profile or an opponent’s profile in the Battle Log to add them.</p></div>'}</section>`:`<form id="clanSearchForm" class="clan-search"><input id="clanSearchQuery" aria-label="Search clans" maxlength="80" placeholder="Search by clan name or tag" value="${esc(query)}">${button('Search','soc-search','blue')}</form><div id="clanDirectory">${W.browseClans(profile,{query,page,limit:12}).map(clanRow).join('')||'<p class="social-empty">No matching clans.</p>'}</div><div class="social-pagination">${button('Previous','soc-prev','blue',page?'':'disabled')}<span>Page ${page+1}</span>${button('Next','soc-next','blue')}</div>`}</div>`;
  ctx.hydrate($('clanContent'));$('clanSearchForm')?.addEventListener('submit',e=>{e.preventDefault();query=$('clanSearchQuery').value;page=0;hub();});
 }
