for(const el of document.querySelectorAll('[data-nav]'))el.innerHTML=navs.map(([id,name,ico])=>`<button class="nav-btn ${el.dataset.nav===id?'selected':''}" data-action="nav-${id}" aria-label="${name}" ${el.dataset.nav===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-word">${word(name)}</span></button>`).join('');
