function renderChests(){const now=Date.now(),poolArena=R.highestArena(profile).number;let html='';for(let i=0;i<4;i++){const c=profile.chests[i];if(!c){html+='<button class="chest-slot empty" data-action="chest-help" aria-label="Empty chest slot"></button>';continue;}const label=RoyaleChestRules.label(c),ready=label.ready,txt=label.title,detail=label.detail;html+=`<button class="chest-slot ${ready?'unlocking':''}" data-action="chest" data-id="${esc(c.id)}" aria-label="${esc(txt+' '+detail+' Arena '+poolArena)}"><div class="slot-header"><strong class="slot-title">${txt}</strong><b class="slot-duration">${detail}</b></div>${icon(E.chestIcon(c.kind))}<span class="slot-arena">Arena ${poolArena}</span></button>`;}if($('chestSlots')._chestHTML!==html){$('chestSlots')._chestHTML=html;$('chestSlots').innerHTML=html;hydrate($('chestSlots'));}setChestLabel('freeChestLabel',profile.freeChestAt>now?'Next in: '+R.timeLabel((profile.freeChestAt-now)/1000):'Open now!');const crowns=Math.max(0,profile.earnedCrowns-profile.crownChestClaimed);setChestLabel('crownChestLabel',crowns>=10?'Ready!':crowns+' / 10');}
