// card-progress-original contains the original source timeline fill states.
const isUnlocked=id=>C.canUseCard(profile,id);
function tile(id,{deck=false,slot=null,replace=false}={}){
 const c=C.CARD_BY_ID[id],unlocked=isUnlocked(id),arenaNumber=R.cardArenaNumber(c,C.DATA.arenas),reached=C.DEFAULT_DECK.includes(id)||arenaNumber<=R.highestArena(profile).number,lockLabel=reached?'Not Found':'Arena '+arenaNumber,owned=profile.decks[profile.activeDeck].includes(id),q=C.upgradeQuote(profile,id),have=profile.copies[id]||0;
 const needed=(profile.cardLevels[id]||9)<C.maxLevel(c.rarity)?(q?.copies||0):0,ready=needed>0&&have>=needed,percent=needed?Math.min(100,have/needed*100):100,progressFrame=needed?(ready?99:Math.min(98,Math.floor(percent*.99))):100;
 return `<button class="card-tile ${unlocked?'':'locked-card'} ${deck&&deckSwapping?'swap-mode':''} ${deck&&slot===swapSlot?'swap-selected':''}" data-action="${replace?'replace-card':deck&&deckSwapping?'swap-deck-card':'card'}" data-id="${esc(id)}" ${slot!==null?`data-slot="${slot}"`:''} aria-label="${esc(c.name)} · ${c.cost} elixir · Level ${profile.cardLevels[id]} · ${have} cards">${cardVisual(id,`<span class="card-level">${unlocked?word('Level '+(profile.cheats.overlevels?(profile.cheatLevels[id]||profile.cardLevels[id]):profile.cardLevels[id])):'Locked'}</span>`)}<span class="cost game-text">${c.id==='mirror'?'?':c.cost}</span><span class="card-progress original ${ready?'ready':''} ${unlocked?'':'locked-progress'}" data-progress-frame="${progressFrame}" style="background-position:${progressFrame%8/7*100}% ${Math.floor(progressFrame/8)/12*100}%" aria-label="${needed?have+' of '+needed+' upgrade cards':'Maximum level'}"><b>${unlocked?(needed?fmt(have)+'/'+fmt(needed):word('Max')):lockLabel}</b></span>${!deck?`<span class="owned-form-badges">${ownedFormBadges(id)}</span>`:''}${!deck&&owned?'<span class="deck-marker">✓</span>':''}</button>`;
}
function renderCards(){const deck=profile.decks[profile.activeDeck],pg=D.page(profile,deckPage);deckPage=pg.page;
 const arrow=(delta,label)=>`<button class="deck-page-arrow" data-action="deck-page" data-index="${pg.page+delta}" aria-label="${label} decks" ${pg.page+delta<0||pg.page+delta>=pg.count?'disabled':''}>${delta<0?'‹':'›'}</button>`;
 $('deckTabs').innerHTML=(pg.count>1?arrow(-1,'Previous'):'')+pg.indices.map(i=>`<button class="deck-tab ${i===profile.activeDeck?'active':''}" data-action="deck" data-index="${i}" aria-label="Battle deck ${i+1}: ${esc(profile.deckNames[i])}" aria-pressed="${i===profile.activeDeck}">${word(String(i+1))}</button>`).join('')+(pg.count>1?arrow(1,'Next'):'')+`<button class="deck-tab deck-add" data-action="add-deck" aria-label="Add battle deck" ${profile.decks.length>=D.MAX_DECKS?'disabled':''}>+</button>`;
 $('deckGrid').innerHTML=deck.map((id,slot)=>tile(id,{deck:true,slot})).join('');decorateFormSlots($('deckGrid'));if(!$('deckFormButton'))$('deckToolbar').insertAdjacentHTML('beforeend','<button id="deckFormButton" class="deck-tool" data-action="deck-forms">Heroes &amp; Evos</button>');$('averageCost').textContent=(deck.reduce((n,id)=>n+C.CARD_BY_ID[id].cost,0)/8).toFixed(1);
 $('deckName').value=profile.deckNames[profile.activeDeck];$('deckPageLabel').textContent=pg.count>1?`${pg.page+1} / ${pg.count}`:'';
 $('deckSwapHint').hidden=!deckSwapping;$('deckToolbar').querySelector('[data-action="deck-swap"]').setAttribute('aria-pressed',String(deckSwapping));filterCards();renderDeckPool();renderCollection();hydrate($('cards'));}
 $('deckName').addEventListener('change',e=>{const r=D.rename(profile,profile.activeDeck,e.target.value);if(r.ok){profile=r.profile;save();renderCards();}});
