// The deck pool is independent of Collection: it excludes IDs in this deck only.
function renderDeckPool(){
 const deck=profile.decks[profile.activeDeck];
 let cards=U.filterCards(C.CARDS,$('deckCardSearch').value,$('deckRarityFilter').value,$('deckCardSort').value,profile.cardLevels,deck);
 cards.sort((a,b)=>Number(!isUnlocked(a.id))-Number(!isUnlocked(b.id)));
 $('deckPoolCount').textContent=String(C.CARDS.length-new Set(deck).size);
 $('deckCollectionGrid').innerHTML=cards.map(c=>tile(c.id)).join('')||'<p class="empty-copy">No matching cards outside this deck.</p>';
 hydrate($('deckCollectionGrid'));hydrate($('deckPoolRegion').querySelector('header'));
}
$('deckCardSearch').addEventListener('input',renderDeckPool);$('deckCardSort').addEventListener('change',renderDeckPool);$('deckRarityFilter').addEventListener('change',renderDeckPool);
function filterCards(){const q=$('cardSearch').value,sort=$('cardSort').value,rarity=$('rarityFilter').value;let cards=U.filterCards(C.CARDS,q,rarity,sort,profile.cardLevels);cards.sort((a,b)=>Number(!isUnlocked(a.id))-Number(!isUnlocked(b.id)));if(collectionReverse)cards.reverse();$('collectionGrid').innerHTML=cards.map(c=>tile(c.id)).join('')||'<p class="empty-copy">No matching cards.</p>';$('collectionCount').textContent=C.CARDS.filter(c=>isUnlocked(c.id)).length+' / '+C.CARDS.length;$('sortLabel').innerHTML=word('By '+sort[0].toUpperCase()+sort.slice(1));hydrate($('collectionGrid'));hydrate($('sortLabel'));}
$('cardSearch').addEventListener('input',filterCards);$('cardSort').addEventListener('change',filterCards);$('rarityFilter').addEventListener('change',filterCards);
function renderCollection(){
 const collection=cardPage==='collection',isCards=collectionPage==='cards';
 $('cards').classList.toggle('library-collection',collection);$('collectionNav').hidden=!collection;$('deckRegion').hidden=collection;$('collectionRegion').hidden=!collection;
 for(const b of $('deckSegments').children){const active=b.dataset.id===cardPage;b.classList.toggle('selected',active);b.setAttribute('aria-selected',String(active));}
 $('collectionNav').innerHTML=U.collectionSections.map(s=>`<button type="button" role="tab" data-action="library-section" data-id="${s.id}" aria-selected="${s.id===collectionPage}" aria-label="${s.name}" class="${s.id===collectionPage?'selected':''}">${s.id==='tower-skins'?'<span class="tower-tab-icon" aria-hidden="true">♜</span>':icon(s.icon)}<span>${s.name}</span></button>`).join('');
 $('collectionHeader').hidden=!isCards;$('collectionGrid').hidden=!isCards;$('collectionFilters').hidden=!isCards||!cardFiltersOpen;$('cosmeticCollection').hidden=isCards;
 if(!isCards){const parent=$('cosmeticCollection');
  if(collectionPage==='emotes'){
   const owned=profile.ownedEmotes.length;
   parent.innerHTML=`<div class="equipped-emotes" aria-label="Battle emotes">${Array.from({length:8},(_,i)=>profile.equippedEmotes[i]?`<button data-action="equip-emote" data-id="${profile.equippedEmotes[i]}" aria-label="Remove emote ${i+1}">${emoteVisual(profile.equippedEmotes[i])}</button>`:'<span class="empty-emote-slot">+</span>').join('')}</div><header class="collection-page-header"><div><h2>Emote Collection</h2><small>Found: ${owned} / ${U.emotes.length}</small></div></header><div class="emote-collection-grid">${U.emotes.map(e=>`<button class="emote-collection-tile ${profile.ownedEmotes.includes(e.id)?'':'not-owned'} ${profile.equippedEmotes.includes(e.id)?'equipped':''}" data-action="collection-emote" data-id="${e.id}" aria-label="${esc(e.name)}${profile.ownedEmotes.includes(e.id)?'':' — Not Found'}">${emoteVisual(e.id)}${profile.equippedEmotes.includes(e.id)?'<b class="equipped-tick">✓</b>':''}${profile.ownedEmotes.includes(e.id)?'':'<small>Not Found</small>'}</button>`).join('')}</div>`;
  }else if(collectionPage==='tower-skins'){
   parent.innerHTML=`<header class="collection-page-header"><div><h2>Tower Collection</h2><small>Customize your Crown Towers!</small></div></header><div class="tower-collection-grid">${U.towerSkins.map(skin=>`<button class="tower-collection-tile ${profile.selectedTowerSkin===skin.id?'equipped':''} ${profile.ownedTowerSkins.includes(skin.id)?'':'not-owned'}" data-action="tower-skin-preview" data-id="${skin.id}" aria-label="${esc(skin.name)}"><canvas data-skin-preview="${skin.id}" width="280" height="300" aria-label="${esc(skin.name)} preview"></canvas><strong>${esc(skin.name)}</strong>${profile.selectedTowerSkin===skin.id?'<span class="equipped-tick">✓</span>':''}${profile.ownedTowerSkins.includes(skin.id)?'':'<small>Not Found</small>'}</button>`).join('')}</div>${towerSkinAvailabilityNote()}`;
  }else{
   parent.innerHTML=`<header class="collection-page-header"><div><h2>Magic Items</h2><small>Use Magic Items to progress faster!</small></div></header><button class="form-inventory-entry" data-action="form-inventory" aria-label="Hero and Evolution inventory"><span class="slot-symbol wild" aria-hidden="true">◆♛</span><span><strong>Heroes &amp; Evolutions</strong><small>${profile.heroCoins} Hero Coins · ${profile.evoWildShards} Wild Shards</small></span><b aria-hidden="true">›</b></button><div class="magic-collection-grid">${U.magicItems.map(item=>{const count=item.kind==='wild'?profile.wildcards[item.rarity]:profile.magicItems[item.id];return `<button class="magic-collection-tile ${count?'':'empty-item'}" data-action="magic-item" data-id="${item.id}" aria-label="${esc(item.name)}, ${count} owned">${magicArt(item)}<strong>${count}</strong><small>${esc(item.name)}</small></button>`;}).join('')}</div><section class="token-inventory"><h3>Trade Tokens</h3><div>${['Common','Rare','Epic','Legendary'].map(r=>`<span>${icon('road-token-'+r.toLowerCase())}<b>${profile.tradeTokens[r]}</b></span>`).join('')}</div></section>`;
  }
 }
 if(collection&&isCards){hydrate($('collectionHeader'));hydrate($('collectionGrid'));}hydrate($('collectionNav'));hydrate($('cosmeticCollection'));renderSkinPreviews($('cosmeticCollection'));
}
function libraryScrollKey(page=cardPage,section=collectionPage){return page==='decks'?'decks':page+':'+section;}
function cardSection(id){if(!['decks','collection'].includes(id))return;libraryScroll[libraryScrollKey()]=$('cardsScroll').scrollTop;cardPage=id;renderCollection();$('cardsScroll').scrollTop=libraryScroll[libraryScrollKey(id)]||0;}
function librarySection(id){if(!U.collectionSections.some(s=>s.id===id))return;libraryScroll[libraryScrollKey()]=$('cardsScroll').scrollTop;cardPage='collection';collectionPage=id;renderCollection();$('cardsScroll').scrollTop=libraryScroll['collection:'+id]||0;}
function magicArt(item){return icon(item.icon,'magic-item-art',item.name);}
let previewScenes=null;
async function renderSkinPreviews(parent){const canvases=[...parent.querySelectorAll('canvas[data-skin-preview]')];if(!canvases.length)return;try{previewScenes=previewScenes||native.ensureScenes([...new Set(['building_tower','chr_king','chr_princess','tower_skins',...U.towerSkins.map(s=>s.scene).filter(Boolean)])]);await previewScenes;for(const cv of canvases){if(!cv.isConnected)continue;const ct=cv.getContext('2d');ct.clearRect(0,0,cv.width,cv.height);ct.save();ct.translate(cv.width/2,cv.height*.81);ct.scale(2,2);native.drawTower(ct,{x:0,y:0,preview:true,team:1,king:true,skin:cv.dataset.skinPreview,hp:1,active:false,heading:Math.PI/2},0);ct.restore();cv.dataset.rendered='true';cv.dataset.facing='front';}}catch(e){previewScenes=null;console.error(e);for(const cv of canvases)cv.setAttribute('aria-label','Tower preview failed to load');toast('Tower previews could not load. Reopen this page to retry.');}}
function towerSkinAvailabilityNote(){const a=RoyaleCosmetics.towerSkinAvailability;return `<div class="skin-availability" role="status"><p>${esc(a.message)}</p><p>${esc(a.detail)}</p>${profile.retiredTowerSkinRefunds.length?'<p class="skin-refund-note">Previous recolor purchases have been refunded in local gems.</p>':''}${profile.towerSkinRefundCredit?`<p class="skin-refund-note">${profile.towerSkinRefundCredit} gems of refund credit will be applied when there is room below your gem limit.</p>`:''}</div>`;}
function towerSkinDetails(id){const skin=U.towerSkins.find(s=>s.id===id);if(!skin)return;const owned=profile.ownedTowerSkins.includes(id),offered=U.rotatingTowerSkins().some(s=>s.id===id);panel('tower-skin',skin.name,`<canvas class="tower-large-preview" data-skin-preview="${id}" width="280" height="300"></canvas>${owned?button(profile.selectedTowerSkin===id?'Selected':'Use','select-tower-skin','green',`data-id="${id}" ${profile.selectedTowerSkin===id?'disabled':''}`):offered?button(skin.cost+' '+icon('gems'),'buy-tower-skin','green',`data-id="${id}" data-hour="${U.hourlyKey()}"`):'<p class="center">Not Found</p>'}`);renderSkinPreviews($('modalPanel'));}
function magicItemDetails(id){const item=U.magicItems.find(i=>i.id===id);if(!item)return;
 const count=item.kind==='wild'?profile.wildcards[item.rarity]:profile.magicItems[id];
 const eligible=E.cardPool(profile).filter(c=>C.canUseCard(profile,c.id)&&profile.cardLevels[c.id]<13&&(!item.rarity||c.rarity===item.rarity));
 const targets=item.kind==='key'?profile.chests.filter(c=>!E.chestReady(c)).map(c=>({id:c.id,name:c.kind+' Chest'})):eligible;
 const descriptions={wild:'Add copies to an already discovered card of this rarity.',book:'Fill the missing copies needed for the next upgrade. The upgrade still costs gold.',coin:'Upgrade without spending gold. You still need the required card copies.',key:'Unlock one chest immediately without completing its remaining wins.'};
 panel('magic-item',item.name,`<div class="magic-item-hero">${magicArt(item)}<b>Owned: ${count}</b></div><p>${descriptions[item.kind]}</p>${targets.length?`<label>Choose ${item.kind==='key'?'a chest':'a card'}<select class="input" id="magicTarget">${targets.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label>`:'<p class="notice">No eligible target right now.</p>'}${item.kind==='wild'?`<label>Copies<input class="input" id="magicCount" type="number" min="1" max="${Math.max(1,count)}" value="1"></label>`:''}${button('Use','use-magic-item','green',`data-id="${id}" ${!count||!targets.length?'disabled':''}`)}`);
}
function show(id){if(id==='clan'||id==='clanChat')id='online';if(!['home','shop','cards','modeDeck','online','events','battle','trophyRoad','crownRoad'].includes(id))return;closeModal(false);if(id!=='battle')sandboxUI.unmount();screen=id;clearTimeout(window.chatPreviewTimer);$('quickChat').hidden=true;$('chatBubble').hidden=true;$('chatBubble').replaceChildren();if(id!=='battle'){$('battleAnnouncement').hidden=true;endFlowStarted=0;const end=$('matchEnd');if(end){end.hidden=true;end.className='match-end';}$('battle')?.classList.remove('match-ending');}for(const s of document.querySelectorAll('.screen'))s.classList.toggle('active',s.id===id);if(id!=='battle'){globalThis.RoyaleModern3D?.beginFrame?.([]);globalThis.RoyaleModern3D?.endFrame?.();if(battle){if(!battle.result&&!battle.isReplay&&battle.warContext?.ticketId){const f=War.forfeit(profile,battle.warContext.ticketId);if(f.ok){profile=f.profile;save();}}archiveBattle(battle);}if($('replayControls'))$('replayControls').hidden=true;battle=null;session=null;selected=null;pointer=null;drag=null;header();}if(id==='home'){updateArena();renderChests();}if(id==='cards'){deckSwapping=false;swapSlot=null;renderCards();}if(id==='modeDeck')renderSpecialDeckScreen();if(id==='shop')renderShop();if(id==='online')renderOnline();if(id==='events')renderEvents();if(id==='crownRoad')renderCrownRoad();fit();hydrate();}
function panel(type,title,html,close=true){returnFocus=document.activeElement;modal=type;$('modalPanel').dataset.kind=type;$('modalPanel').innerHTML=`${close?`<button class="modal-close" data-action="close" aria-label="Close">${icon('close')}</button>`:''}<h2 class="modal-title">${word(title)}</h2>${html}`;$('overlay').classList.add('open');$('overlay').setAttribute('aria-label',title.replace(/<[^>]*>/g,''));$('modalPanel').scrollTop=0;hydrate($('modalPanel'));setTimeout(()=>$('modalPanel').querySelector('button,input,select')?.focus({preventScroll:true}),0);}
function closeModal(resume=true){chestOpening.close();modal=null;$('overlay').classList.remove('open');if(resume&&battle?.paused&&!battle.result){battle.paused=false;last=0;acc=0;}if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
function details(id,level=profile.cheats.overlevels?(profile.cheatLevels[id]||profile.cardLevels[id]):profile.cardLevels[id]){
 if(!C.CARD_BY_ID[id])return;currentCard=id;currentFormId=null;detailLevel=level;
 const c=C.cardAt(id,level),e=c.entity?C.entityDef(c.entity,level):null,unlocked=isUnlocked(id),arenaNumber=R.cardArenaNumber(c,C.DATA.arenas),reached=C.DEFAULT_DECK.includes(id)||arenaNumber<=R.highestArena(profile).number,owned=profile.cardLevels[id],quote=C.upgradeQuote(profile,id),have=profile.copies[id]||0,needed=owned<C.maxLevel(c.rarity)?quote.copies:0,progressFrame=needed?(have>=needed?99:Math.min(98,Math.floor(Math.min(100,have/needed*100)*.99))):100;
 const stats=[],advanced=[];if(c.hp)stats.push(['Hitpoints',fmt(c.hp)]);if(c.damage)stats.push([c.damageMode==='per second'?'Damage per second':c.damageMode==='per wave'?'Damage per wave':'Damage',fmt(c.damage)]);
 if(e){if(e.damage)stats.push(['Hit speed',Number(e.interval.toFixed(2))+' sec']);if(e.speedTiles)stats.push(['Speed',({30:'Very Slow',45:'Slow',60:'Medium',90:'Fast',120:'Very Fast'})[e.source.Speed]||e.speedTiles+' tiles/sec']);if(e.range)stats.push(['Range',e.range<2?'Melee: '+(e.range<=.8?'Short':e.range<=1.2?'Medium':'Long'):e.range+' tiles']);stats.push(['Targets',e.buildingsOnly?'Buildings':e.troopsOnly?(e.targetsAir?'Air & ground troops':'Ground troops'):e.targetsAir?'Air & ground':'Ground']);advanced.push(['Deployment',e.deploy+' sec'],['First attack',Number(e.firstHit.toFixed(3))+' sec']);if(e.speedTiles)advanced.push(['Movement',e.speedTiles+' tiles/sec']);}else if(c.radiusTiles)stats.push(['Radius',c.radiusTiles+' tiles']);
 if(e?.shield)stats.push(['Shield hitpoints',fmt(e.shield)]);if(c.count>1)stats.push(['Count','×'+c.count]);if(e?.minRange)stats.push(['Minimum range',e.minRange+' tiles']);if(e?.life)stats.push(['Lifetime',e.life+' sec']);if(c.duration)stats.push(['Duration',c.duration+' sec']);if(c.spellRange)stats.push(['Travel range',c.spellRange+' tiles']);if(c.crownDamage!==null&&c.spell)stats.push(['Crown tower damage',fmt(c.crownDamage)]);if(c.spawnEntity){const child=C.entityDef(c.spawnEntity,level);stats.push(['Troop hitpoints',fmt(child.hp)],['Troop damage',fmt(child.damage)]);}
 panel('card',esc(c.name),`<div class="card-info-hero" data-rarity="${c.rarity.toLowerCase()}"><div class="card-info-portrait">${cardVisual(id)}<span class="detail-elixir">${c.id==='mirror'?'?':c.cost}</span></div><div class="card-info-summary"><div class="rarity">${c.rarity} · ${c.kind}</div><strong class="card-owned-level">${unlocked?'Level '+owned:reached?'Not Found':'Arena '+arenaNumber}</strong>${unlocked?`<div class="card-info-progress ${needed&&have>=needed?'ready':''}" data-progress-frame="${progressFrame}" style="background-position:${progressFrame%8/7*100}% ${Math.floor(progressFrame/8)/12*100}%"><i style="width:${needed?Math.min(100,have/needed*100):100}%"></i><b>${needed?fmt(have)+'/'+fmt(needed):'Max Level'}</b></div>`:`<p class="card-unlock-hint">${reached?'Find your first card to unlock it.':'Unlocks in Arena '+arenaNumber+'.'}</p>`}<label class="card-level-picker">Card level <select id="detailLevel" aria-label="Card stat level">${Array.from({length:(profile.cheats.overlevels?31:C.maxLevel(c.rarity)+1)-C.baseLevel(c.rarity)},(_,i)=>i+C.baseLevel(c.rarity)).map(l=>`<option value="${l}" ${l===level?'selected':''}>Level ${l}</option>`).join('')}</select></label></div></div><p class="card-info-description">${esc(c.description)}</p><div class="card-info-stats">${stats.map(([name,value])=>`<div class="stat-box"><span>${name}</span><b>${esc(value)}</b></div>`).join('')}</div><div class="row-actions">${button(!RoyaleModernActions.canDeployCard(null,C.CARD_BY_ID[id]).ok?'Unavailable':!unlocked?'Locked':!profile.cheats.duplicates&&profile.decks[profile.activeDeck].includes(id)?'In Deck':'Use','use-card','blue',`data-id="${id}" ${!RoyaleModernActions.canDeployCard(null,C.CARD_BY_ID[id]).ok||!unlocked||!profile.cheats.duplicates&&profile.decks[profile.activeDeck].includes(id)?'disabled':''}`)}${button(owned===C.maxLevel(c.rarity)?'Max Level':`Upgrade <small>${icon('gold')} ${fmt(quote.gold)}</small>`,'upgrade','green',`data-id="${id}" ${!quote.canUpgrade?'disabled':''} aria-label="Upgrade ${esc(c.name)}"`)}</div>${formCardActions(id)}<details class="card-advanced"><summary>More details</summary><div class="stats-grid">${advanced.map(([name,value])=>`<div class="stat-box">${name}<b>${esc(value)}</b></div>`).join('')}</div><p>${C.features(c).map(f=>`<span class="tag">${esc(f)}</span>`).join('')}</p>${button('Original card data','source-card','blue',`data-id="${id}"`)}</details>`);
 $('detailLevel').addEventListener('change',e=>details(id,Number(e.target.value)));
 $('modalPanel').querySelector('.card-advanced').addEventListener('toggle',event=>{if(event.target.open)hydrate(event.target);});
}
function useCard(id,formId=null){if(!isUnlocked(id)){toast('Unlock this card first');return;}const chosen=F.get(formId);if(chosen&&!formSupported(chosen)||!chosen&&!RoyaleModernActions.canDeployCard(null,C.CARD_BY_ID[id]).ok){toast('This card is not available yet.');return;}currentCard=id;currentFormId=formId;panel('replace','Choose a Deck Slot',`<p class="center">Choose a position for <b>${esc(chosen?.name||C.CARD_BY_ID[id].name)}</b>. Special slots activate an eligible unlocked form.</p><div class="replace-grid">${profile.decks[profile.activeDeck].map((c,slot)=>tile(c,{deck:true,slot,replace:true})).join('')}</div>`);const grid=$('modalPanel').querySelector('.replace-grid');decorateFormSlots(grid);for(const [slot,el]of [...grid.children].entries()){const options={...formContext(),...(formId?{formId}:{})},r=D.setCard(profile,slot,id,options);if(!r.ok){el.disabled=true;el.title=r.reason;el.setAttribute('aria-label',el.getAttribute('aria-label')+'. '+r.reason);}}}
function sourceCard(id){const c=C.cardAt(id,detailLevel);const raw={card:c.source,entity:c.entity?C.DATA.entities[c.entity]:null,projectile:C.DATA.projectiles[c.entity?C.DATA.entities[c.entity].Projectile:c.source.Projectile]||null,area:C.DATA.areas[c.source.AreaEffectObject]||null};panel('source','Original Card Data',`<p class="small">${esc(c.name)} · ${esc(C.DATA.snapshot)}. Values below are the unmodified source records; displayed health and damage apply the source rarity-level multipliers.</p><pre style="font-size:12px;white-space:pre-wrap;word-break:break-word;background:#c7d5e3;padding:12px;max-height:590px;overflow:auto;user-select:text">${esc(JSON.stringify(raw,null,2))}</pre>${button('Back to Card','card','blue',`data-id="${id}"`)}`);}
function referenceBanner(text,kind='',action=''){return `<div class="reference-banner ${kind}"><h2>${word(text)}</h2>${action?`<button class="info-button" data-action="${action}" aria-label="About ${esc(text)}">${icon('info')}</button>`:''}</div>`;}
function shopOffer(o,i,dealKey,lightning=false,daily=false,gem=false){
 if(o.locked)return `<article class="shop-offer locked-offer ${o.rarity.toLowerCase()}" data-rarity="${o.rarity}"><h3>${word(o.rarity)}</h3><div class="locked-offer-art">${icon('cards')}</div><strong>Locked</strong><small>Reach an arena with ${o.rarity.toLowerCase()} cards</small></article>`;
 const c=C.CARD_BY_ID[o.id],bought=gem?profile.gemShop.purchased.includes(i):(daily?profile.dailyPurchases:lightning?profile.lightningPurchases:profile.shopPurchases)[dealKey+':'+i],currency=gem?'gems':'gold',q=C.upgradeQuote(profile,o.id),have=profile.copies[o.id],need=profile.cardLevels[o.id]===C.maxLevel(c.rarity)?0:q.copies;
 return `<article data-rarity="${c.rarity}" class="shop-offer card-shop-offer ${c.rarity.toLowerCase()} ${bought?'purchased':''}"><h3 class="offer-title">${esc(c.name)}</h3><div class="offer-rarity">${word(c.rarity)}</div><button class="offer-portrait" data-action="card" data-id="${o.id}" aria-label="View ${esc(c.name)}">${cardVisual(o.id)}</button><div class="offer-quantity" aria-label="${o.quantity} cards"><b>×${fmt(o.quantity)}</b><span>cards</span></div>${bought?`<div class="offer-collected" role="status">${icon('ref-tick')}<b>${word('Collected!')}</b></div>`:`<div class="offer-copy-progress ${have>=need?'ready':''}" ${need?`role="progressbar" aria-label="${esc(c.name)} upgrade copies" aria-valuemin="0" aria-valuemax="${need}" aria-valuenow="${Math.min(have,need)}" aria-valuetext="${have} of ${need} copies"`:'role="status" aria-label="Maximum card level"'}><i style="width:${need?Math.min(100,have/need*100):100}%"></i><b aria-hidden="true">${need?fmt(have)+'/'+fmt(need):'MAX'}</b></div><button class="offer-price" data-action="${gem?'buy-gem-card':daily?'daily-shop-offer':lightning?'buy-lightning-card':'buy-card'}" data-index="${i}" data-window="${dealKey}" data-card="${o.id}" data-quantity="${o.quantity}" aria-label="Buy ${o.quantity} ${esc(c.name)} for ${o.price} ${currency}"><strong>${fmt(o.price)}</strong>${icon(currency)}</button>`}</article>`;
}
// Connected content presentation
function contentRewardEntries(reward={}){
 const rows=[];
 for(const id of reward.unlockedForms||[]){const f=F.get(id);if(f)rows.push({kind:'form',targetId:id,name:f.name,count:1});}
 for(const [id,count]of Object.entries(reward.formShards||{})){const f=F.get(id);if(f&&count>0)rows.push({kind:'form-shard',targetId:id,name:f.name+' Shards',count});}
 for(const [id,count]of Object.entries(reward.towerTroops||{})){const c=globalThis.RoyaleTowerTroops?.catalog.find(c=>c.id===id);if(c&&count>0)rows.push({kind:'tower-troop',targetId:id,name:c.name,count});}
 for(const [kind,key,name]of [['hero-coins','heroCoins','Hero Coins'],['wild-shards','evoWildShards','Wild Evolution Shards']])if(reward[key]>0)rows.push({kind,name,count:reward[key]});
 for(const item of reward.sourceCosmetics||[]){const id=MR.resolveCosmetic(item.kind,item.id);if(!id)continue;const skin=item.kind==='TowerSkins',c=(skin?U.towerSkins:U.emotes).find(c=>c.id===id);if(c)rows.push({kind:skin?'tower-skin':'emote',targetId:id,name:c.name,count:item.count||1});}
 return rows;
}
function contentArt(row){
 if(['hero','evo-shard','form','form-shard'].includes(row.kind)){const f=F.get(row.targetId);return f?cardVisual(f.baseCardId,formBadge(f.id),false,{formId:f.id}):'';}
 if(row.kind==='tower-troop')return towerTroopVisual(row.targetId);
 if(row.kind==='tower-skin')return `<canvas data-skin-preview="${esc(row.targetId)}" width="280" height="300" aria-label="${esc(row.name)}"></canvas>`;
 if(row.kind==='emote')return emoteVisual(row.targetId);
 const currencyKey=row.kind==='hero-coins'?'reward-hero-coins':'reward-wild-shards';if(B.uiImages[currencyKey])return icon(currencyKey,'content-currency-icon',row.name);return `<span class="content-currency ${row.kind}" aria-hidden="true">${row.kind==='hero-coins'?'HC':'◆'}</span>`;
}
function contentRewardMarkup(reward,{actions=false,compact=false}={}){
 const rows=contentRewardEntries(reward);if(!rows.length)return '';
 return `<div class="content-reward-grid ${compact?'compact':''}">${rows.map(row=>{
  const form=F.get(row.targetId),owned=form?profile.unlockedForms.includes(form.id):row.kind==='tower-skin'?profile.ownedTowerSkins.includes(row.targetId):row.kind==='emote'?profile.ownedEmotes.includes(row.targetId):row.kind==='tower-troop'?profile.unlockedTowerTroops?.includes(row.targetId):false;
  let action='';if(actions){if(form)action=owned?button('Use '+(form.kind==='hero'?'Hero':'Evolution'),'use-form','blue',`data-id="${esc(form.id)}" ${!formSupported(form)?'disabled':''}`):button('View Inventory','form-inventory','blue');else if(row.kind==='tower-skin'&&owned)action=button(profile.selectedTowerSkin===row.targetId?'Selected':'Use','select-tower-skin','blue',`data-id="${esc(row.targetId)}" ${profile.selectedTowerSkin===row.targetId?'disabled':''}`);else if(row.kind==='emote'&&owned)action=button(profile.equippedEmotes.includes(row.targetId)?'Equipped':'Equip','equip-emote','blue',`data-id="${esc(row.targetId)}" ${profile.equippedEmotes.includes(row.targetId)?'disabled':''}`);else if(row.kind==='tower-troop')action=button('View Tower Troops','tower-troops','blue');else action=button('View Inventory','form-inventory','blue');}
  return `<article class="content-reward-item" data-reward-kind="${row.kind}" data-reward-id="${esc(row.targetId||'')}"><div class="content-reward-art">${contentArt(row)}</div><strong>${row.kind==='form'?'Unlocked':'× '+fmt(row.count)}</strong><span>${esc(row.name)}</span>${owned?'<small>In your collection</small>':''}${action}</article>`;
 }).join('')}</div>`;
}
let contentShopKind='hero',contentShopPage=0;
function connectedShop(){
 const all=globalThis.RoyaleShopModel?.offers(profile,{registry:F,towerRegistry:globalThis.RoyaleTowerTroops}).filter(o=>['hero','evo-shard','tower-troop'].includes(o.kind))||[],kinds=['hero','evo-shard','tower-troop'].filter(kind=>all.some(o=>o.kind===kind));
 if(!kinds.includes(contentShopKind))contentShopKind=kinds[0];const selected=all.filter(o=>o.kind===contentShopKind),pages=Math.ceil(selected.length/6);contentShopPage=Math.max(0,Math.min(contentShopPage,pages-1));const offers=selected.slice(contentShopPage*6,contentShopPage*6+6);
 if(!offers.length)return '';
 return `<section id="contentShop" class="shop-deals-section connected-content-shop"><h2>Heroes, Evolutions &amp; Tower Troops</h2><nav class="content-shop-tabs" aria-label="Card types">${kinds.map(kind=>`<button data-action="content-shop-kind" data-kind="${kind}" aria-pressed="${kind===contentShopKind}">${({'hero':'Heroes','evo-shard':'Evolutions','tower-troop':'Tower Troops'})[kind]}</button>`).join('')}</nav><p class="shop-countdown">Choose a Hero, collect Evolution Shards, or upgrade your Tower Troops.</p><div class="shop-grid">${offers.map(o=>{
  const f=F.get(o.targetId),c=globalThis.RoyaleTowerTroops?.catalog.find(c=>c.id===o.targetId),name=f?.name||c?.name||o.targetId,row={kind:o.kind,targetId:o.targetId,name},label=o.kind==='evo-shard'?'1 Evolution Shard':o.kind==='hero'?'Unlock Hero':fmt(o.quantity)+' Tower Troop Cards',currency=({heroCoins:'Hero Coins',evoWildShards:'Wild Shards',gold:'Gold',gems:'Gems'})[o.currency]||o.currency;
  return `<article class="shop-offer content-shop-offer" data-content-kind="${o.kind}" data-content-target="${esc(o.targetId)}"><h3>${esc(name)}</h3><div class="offer-rarity">${esc(label)}</div><div class="offer-portrait">${contentArt(row)}</div><p class="content-offer-state">${esc(o.owned?'Already unlocked':/Unavailable|Unsupported/i.test(o.reason)?'Not available in battle yet':o.reason||'Available')}</p>${o.owned?button(f?'Use '+(f.kind==='hero'?'Hero':'Evolution'):'View Tower Troops',f?'use-form':'tower-troops','blue',`data-id="${esc(o.targetId)}" ${!o.supported?'disabled':''}`):button(fmt(o.price)+' '+currency,'buy-content-offer','gold',`data-id="${esc(o.id)}" data-window="${esc(o.window)}" data-fingerprint="${esc(o.fingerprint)}" ${!o.available?'disabled':''}`)}</article>`;
 }).join('')}</div>${pages>1?`<nav class="content-shop-pages" aria-label="More offers"><button data-action="content-shop-page" data-index="${contentShopPage-1}" ${contentShopPage===0?'disabled':''}>Previous</button><span>${contentShopPage+1} / ${pages}</span><button data-action="content-shop-page" data-index="${contentShopPage+1}" ${contentShopPage+1>=pages?'disabled':''}>Next</button></nav>`:''}</section>`;
}
function passRewards(){
 const tiers=Array.from({length:35},(_,tier)=>{const reward=E.passReward(profile,tier),ready=profile.earnedCrowns>=(tier+1)*10,claimed=profile.passClaimed.includes(tier);return `<article class="pass-reward-row" data-pass-tier="${tier}"><h3>Tier ${tier+1} · ${(tier+1)*10} crowns</h3><p>${reward.gold?fmt(reward.gold)+' Gold':''}${reward.cards?.length?' · '+reward.cards.reduce((sum,c)=>sum+c.count,0)+' cards':''}</p>${contentRewardMarkup(reward,{compact:true})}${button(claimed?'Collected':ready?'Collect':'Locked','claim-pass','blue',`data-index="${tier}" ${claimed||!ready?'disabled':''}`)}</article>`;}).join('');
 panel('pass-rewards','Crown Rewards',`<p class="small">Earn crowns in regular battles. Bonus rewards are local practice rewards.</p><div class="pass-reward-list">${tiers}</div>`);renderSkinPreviews($('modalPanel'));
}
// End connected content presentation

function dailyFreeOffer(o,i,key){const claimed=profile.dailyPurchases[key+':'+i],detail=i<2?'':'×'+o.quantity+' '+o.rarity;return `<article class="shop-offer daily-free-offer ${claimed?'purchased':''}" data-free-slot="${i}"><h3>${word(o.name)}</h3><div class="daily-reward-art">${icon(o.icon,'',o.name)}</div>${detail?`<p>${detail}</p>`:''}${button(claimed?'Collected!':'Free','daily-shop-offer','green',`data-index="${i}" data-window="${key}" ${claimed?'disabled':''}`)}</article>`;}
function renderShop(){const now=Date.now(),gemRotation=profile.gemShop.rotation,gemOffers=E.gemOffers(profile),dailyKey=E.dailyWindow(now),daily=E.dailyOffers(now,profile),dealKey=E.shopWindow(now),lightningKey=E.lightningWindow(now),lightning=E.lightningOffers(now,profile),hour=U.hourlyKey(now),offers=E.offers(now,profile),scroll=$('shopContent').scrollTop;
 $('shopContent').dataset.gemRotation=String(gemRotation);$('shopContent').dataset.dailyWindow=dailyKey;$('shopContent').dataset.window=dealKey;$('shopContent').dataset.hour=String(hour);$('shopContent').dataset.lightningWindow=lightningKey;
 $('shopContent').innerHTML=`${connectedShop()}<section id="dailyShop" class="shop-deals-section daily-shop">${referenceBanner('Daily Shop','teal','daily-shop-info')}<p class="shop-countdown">New offers in <b id="dailyRefresh">${U.refreshIn(now,86400000)}</b></p><div class="shop-grid daily-offers">${daily.map((o,i)=>i<3?dailyFreeOffer(o,i,dailyKey):shopOffer(o,i,dailyKey,false,true)).join('')}</div></section><section id="gemShop" class="shop-deals-section gem-shop">${referenceBanner('Gem Shop','purple','gem-shop-info')}<p class="shop-countdown gem-shop-progress">Refreshes after two purchases · <b id="gemShopProgress">${profile.gemShop.purchased.length} / 2</b></p><div class="shop-grid gem-offers">${gemOffers.map((o,i)=>shopOffer(o,i,gemRotation,false,false,true)).join('')}</div></section><section class="shop-deals-section">${referenceBanner('Hour Shop','teal','deals-info')}<p class="shop-countdown">New cards in <b id="shopRefresh">${U.refreshIn(now)}</b></p><div class="shop-grid">${offers.map((o,i)=>shopOffer(o,i,dealKey)).join('')}</div></section>
 <section id="lightningShop" class="shop-deals-section lightning-shop">${referenceBanner('Lightning Shop','purple','lightning-info')}<p class="shop-countdown">New cards in <b id="lightningRefresh">${U.refreshIn(now,600000)}</b></p><div class="shop-grid lightning-offers">${lightning.map((o,i)=>shopOffer(o,i,lightningKey,true)).join('')}</div></section>
 <section class="shop-chest-section">${referenceBanner('Treasure Chests','teal')}<div class="shop-grid chests">${E.chestOffers(profile).map(({kind,name,price,icon:art,locked,rarity})=>`<article class="shop-offer chest-offer ${locked?'locked-offer':''}"><h3>${esc(name)}</h3>${icon(art,'',name)}<button class="offer-price" data-action="buy-chest" data-kind="${kind}" aria-label="${esc(name+' · '+price+' gems'+(locked?' · Reach an arena with '+rarity+' cards':''))}" ${locked?'disabled title="Reach an arena with '+rarity+' cards"':''}><strong>${price}</strong>${icon('gems')}</button></article>`).join('')}</div></section>
 <section id="emoteShop" class="shop-emote-section">${referenceBanner('Emotes','purple','emotes-info')}<p class="shop-countdown">New emotes in <b data-hour-countdown>${U.refreshIn(now,3600000)}</b></p><div class="shop-grid emote-offers">${U.rotatingEmotes(now).map(e=>`<article class="shop-offer emote-offer"><button class="emote-preview" data-action="emote-preview" data-id="${e.id}" aria-label="Preview ${esc(e.name)}">${emoteVisual(e.id)}</button><button class="offer-price" data-action="buy-emote" data-id="${e.id}" data-hour="${hour}" ${profile.ownedEmotes.includes(e.id)?'disabled':''}><strong>${profile.ownedEmotes.includes(e.id)?word('Owned'):e.cost}</strong>${profile.ownedEmotes.includes(e.id)?'':icon('gems')}</button></article>`).join('')}</div><div class="shop-shelf" aria-hidden="true"></div></section>
 <section id="towerSkinShop" class="shop-emote-section">${referenceBanner('Tower Skins','purple')}<div class="shop-grid tower-skin-offers">${U.rotatingTowerSkins(now).map(skin=>`<article class="shop-offer"><button class="tower-shop-preview" data-action="tower-skin-preview" data-id="${skin.id}" aria-label="Preview ${esc(skin.name)}"><canvas data-skin-preview="${skin.id}" width="280" height="300" aria-label="${esc(skin.name)}"></canvas><strong>${esc(skin.name)}</strong></button><button class="offer-price" data-action="buy-tower-skin" data-id="${skin.id}" data-hour="${hour}" ${profile.ownedTowerSkins.includes(skin.id)?'disabled':''}><strong>${profile.ownedTowerSkins.includes(skin.id)?word('Owned'):skin.cost}</strong>${profile.ownedTowerSkins.includes(skin.id)?'':icon('gems')}</button></article>`).join('')}</div>${towerSkinAvailabilityNote()}</section>
`;
 hydrate($('shopContent'));$('shopContent').scrollTop=scroll;renderSkinPreviews($('shopContent'));
}
function refreshShopClock(){if(screen!=='shop')return;const now=Date.now(),node=$('shopContent');if(node.dataset.gemRotation!==String(profile.gemShop.rotation)||node.dataset.dailyWindow!==E.dailyWindow(now)||node.dataset.window!==E.shopWindow(now)||node.dataset.hour!==String(U.hourlyKey(now))||node.dataset.lightningWindow!==E.lightningWindow(now)){renderShop();return;}if($('dailyRefresh'))$('dailyRefresh').textContent=U.refreshIn(now,86400000);if($('shopRefresh'))$('shopRefresh').textContent=U.refreshIn(now);if($('lightningRefresh'))$('lightningRefresh').textContent=U.refreshIn(now,600000);for(const e of node.querySelectorAll('[data-hour-countdown]'))e.textContent=U.refreshIn(now,3600000);}
function openCurrency(){toast('Gold and gems are earned through rewards. Currency purchases are disabled.');}
async function chestRewards(result,kind,title,afterCommit){if(!result.ok){transaction(result,title);return;}const owned=[...profile.unlockedCards];profile=result.profile;save();header();renderChests();if(screen==='shop')renderShop();afterCommit?.();try{await chestOpening.open(result.reward,{kind,title,owned});}catch(error){console.error(error);rewards(result.reward,title);}}
function transaction(result,title='Rewards'){if(!result.ok){toast(result.reason);sound('error');return;}profile=result.profile;save();header();if(screen==='shop')renderShop();if(screen==='cards')renderCards();renderChests();if(result.reward)rewards(result.reward,title);else toast(title);sound('reward');}
function rewards(reward,title='Rewards'){const amounts=[...Object.entries(reward.magicItems||{}).filter(([,v])=>v>0).map(([id,v])=>'+'+v+' '+esc(U.magicItems.find(x=>x.id===id)?.name||id)),reward.gold?icon('gold')+' +'+fmt(reward.gold)+' Gold':'',reward.gems?icon('gems')+' +'+fmt(reward.gems)+' Gems':'',...Object.entries(reward.wildcards||{}).map(([k,v])=>'+'+v+' '+k+' Wild Cards'),...Object.entries(reward.tradeTokens||{}).map(([k,v])=>'+'+v+' '+k+' Trade Token'+(v===1?'':'')+(v?' (saved locally)':'')),...Object.entries(reward.magicItems||{}).map(([id,n])=>'+'+n+' '+esc(U.magicItems.find(i=>i.id===id)?.name||id)),reward.emote?'Emote added to your collection':''].filter(Boolean);panel('rewards',title,`<div class="reward-chest">${icon(reward.emote?'emote-'+reward.emote:reward.magicItems?'magic-'+Object.keys(reward.magicItems)[0]:reward.wildcards?'road-wild-'+Object.keys(reward.wildcards)[0].toLowerCase():reward.gems?'gem-chest':'gold-chest')}</div><div class="reward-summary">${amounts.map(x=>'<p>'+x+'</p>').join('')}</div><div class="reward-list">${(reward.cards||[]).map(c=>`<div class="center">${cardVisual(c.id)}<p class="small"><b>× ${c.count}</b><br>${esc(C.CARD_BY_ID[c.id].name)}</p></div>`).join('')}</div>${contentRewardMarkup(reward,{actions:true})}${button('Collect','close','green')}`);renderSkinPreviews($('modalPanel'));}
function chest(id){const c=profile.chests.find(x=>x.id===id);if(!c)return;if(E.chestReady(c)){chestRewards(E.openChest(profile,id),c.kind,({gem:'Gem',silver:'Silver',gold:'Golden',magic:'Magical',legendary:'Legendary',epic:'Epic',giant:'Giant'}[c.kind]||'Treasure')+' Chest');return;}panel('chest','Chest',`<div class="reward-chest">${icon(E.chestIcon(c.kind))}</div><p class="center">Locked · ${RoyaleChestRules.label(c).detail} remaining</p><div class="notice">Win regular battles to unlock this chest. Wins advance every occupied chest slot; the battle that earns a new chest does not count toward that chest.</div>${profile.magicItems['chest-key']?button('Use Chest Key','chest-key','green',`data-id="${id}"`):''}`);}
function renderClan(){social.hub();}
function joinOptions(){social.browse();}
function clanMembers(){social.clanPage(profile.world.currentClan);}
function clanWar(){social.war();}
function refreshClanViews(){if(screen==='clanChat')social.chat();else if(screen==='clan')social.hub();}
function renderClanChat(){social.chat();}
function emotePicker(){panel('clan-emotes','Emotes',`<div class="emote-picker">${U.emotes.filter(e=>profile.ownedEmotes.includes(e.id)).map(e=>`<button data-action="send-emote" data-id="${e.id}" aria-label="Send ${e.name}">${emoteVisual(e.id)}</button>`).join('')}</div>`);}
function renderOnline(){
 const node=$('onlineContent');if(!node)return;node.innerHTML=`<section class="online-soon-card">${icon('team-icon')}<h2>Online Play</h2><strong>Coming Soon</strong><p>Real-time matchmaking, friends and team battles will appear here in a future update.</p><div class="online-soon-features"><span>1v1</span><span>2v2</span><span>3v3</span><span>5v5</span></div></section>`;hydrate(node);
}
function renderEvents(){
 const groups=[
  ['Team Battles', [['TeamVsTeam','2v2','You + an AI teammate vs two rivals','team-icon'],['Team3v3','3v3','Three-player teams · Three detailed arena themes','team-icon'],['TeamRumble','Team Rumble','5v5 King elimination · Three detailed arena themes','team-icon']]],
  ['Touchdown', [['Touchdown','Touchdown','Official-style Touchdown stadium · First to 3','challenge'],['Touchdown2v2','2v2 Touchdown','Two-player teams in the Touchdown stadium','team-icon'],['Touchdown3v3','3v3 Touchdown','Three-player teams on the wider stadium field','team-icon']]],
  ['Deck Modes', [['FourCardDeck','4 Card Deck','Four-card cycle','cards'],['SixCardDeck','6 Card Deck','Four in hand · Two in cycle','cards'],['TwelveCardDeck','12 Card Deck','Four in hand · Eight in cycle','cards'],['RandomDeck','Random Deck','Fresh random deck every battle','cards']]],
  ['Elixir', [['TwentyElixir','20 Elixir','Hold up to 20 elixir','event-double'],['UncappedElixir','Uncapped Elixir','Normal generation with no storage cap','event-double'],['DoubleElixir','Double Elixir','2× from the start','event-double'],['TripleElixir','Triple Elixir','3× elixir','event-triple'],['RampUp','Ramp Up','Elixir grows during battle','event-ramp'],['7xElixir','Infinite Elixir','Seven-times elixir','event-double']]],
  ['Other Modes', [['SuddenDeath','Sudden Death','First tower wins','event-sudden'],['OneShot','One Shot','1 HP towers · Restricted cards','event-sudden'],['BridgeBattle','Bridge','Single-lane battle · Three detailed arena themes','challenge'],['Default','Classic Challenge','Level 9 · Separate decks','challenge'],['Sandbox','Sandbox','Any card, map and level','training']]]
 ];
 $('eventsContent').innerHTML=`<div class="events-heading">${icon('challenge')}<div><h3>${word('Other modes')}</h3><p>Organized custom battles · Level 11 · No Trophy Road changes</p></div></div><div class="mode-groups">${groups.map(([title,modes])=>`<section class="mode-group"><h2>${esc(title)}</h2><div class="events-grid">${modes.map(([mode,name,desc,ico])=>`<article class="event-card">${icon(ico)}<div><h3>${word(name)}</h3><p>${desc}</p>${button('Play',mode==='Sandbox'?'sandbox':mode==='RandomDeck'?'random-mode':D.MODE_DECKS[mode]?'special-deck-builder':'mode','gold',mode==='Sandbox'?'':`data-mode="${mode}"`)}</div></article>`).join('')}</div></section>`).join('')}</div>`;hydrate($('eventsContent'));
}


function specialDeckBuilder(mode=specialMode){
 if(!D.MODE_DECKS[mode])return;if(mode!==specialMode){specialMode=mode;specialSlot=0;specialQuery='';specialDeckPage=0;}if(screen!=='modeDeck'){show('modeDeck');return;}renderSpecialDeckScreen();
}
function modeDeckRule(mode,state){return mode==='OneShot'?'First tower destroyed wins. No spells, Mortar, X-Bow, Miner or Goblin Drill.':mode==='TwelveCardDeck'?'Four cards in hand, eight in the cycle.':mode==='SixCardDeck'?'Four cards in hand, two in the cycle.':mode==='FourCardDeck'?'Fast four-card cycle.':mode==='UncappedElixir'?'Normal elixir generation with no storage cap.':mode.startsWith('Touchdown')?'Get a troop across the enemy goal line. First to 3 touchdowns wins.':'A separate saved deck for '+state.name+'.';}
function modeDeckCard(id,slot,state){const c=C.CARD_BY_ID[id];return `<button class="card-tile mode-card-tile ${slot===specialSlot?'chosen':''}" data-action="special-deck-slot" data-index="${slot}" aria-label="Slot ${slot+1}: ${esc(c.name)}">${cardVisual(id,`<span class="card-level">${word('Level 11')}</span>`)}<span class="cost game-text">${c.cost}</span></button>`;}
function modeCollectionCard(id,state){const c=C.CARD_BY_ID[id],inDeck=!state.duplicates&&state.deck.includes(id);return `<button class="card-tile mode-card-tile ${inDeck?'in-deck':''}" data-action="special-deck-pick" data-id="${id}" aria-label="Use ${esc(c.name)}">${cardVisual(id,`<span class="card-level">${word('Level 11')}</span>`)}<span class="cost game-text">${c.cost}</span><span class="owned-form-badges">${ownedFormBadges(id)}</span>${inDeck?'<span class="deck-marker">✓</span>':''}</button>`;}
function renderSpecialDeckScreen(){
 if(!D.MODE_DECKS[specialMode])return;const state=D.modeState(profile,specialMode),pg=D.modePage(profile,specialMode,specialDeckPage);specialDeckPage=pg.page;const avg=state.deck.reduce((n,id)=>n+(C.CARD_BY_ID[id]?.cost||0),0)/Math.max(1,state.deck.length);
 $('modeDeckTitle').textContent=state.name;$('modeDeckRule').textContent=modeDeckRule(specialMode,state);$('modeDeckAverage').textContent=avg.toFixed(1);$('modeDeckName').value=state.names[state.active]||('Deck '+(state.active+1));$('modeDeckPageLabel').textContent=pg.count>1?`${pg.page+1} / ${pg.count}`:'';$('modeDeckCount').textContent=`${state.deck.length}/${state.size} cards`;document.querySelector('#modeDeck .mode-deck-summary>span:last-child').textContent='All eligible cards · Level 11';
 const arrow=(delta,label)=>`<button class="deck-page-arrow" data-action="special-deck-page" data-page="${pg.page+delta}" aria-label="${label} decks" ${pg.page+delta<0||pg.page+delta>=pg.count?'disabled':''}>${delta<0?'‹':'›'}</button>`;
 $('modeDeckTabs').innerHTML=(pg.count>1?arrow(-1,'Previous'):'')+pg.indices.map(i=>`<button class="deck-tab ${i===state.active?'active':''}" data-action="special-deck-select" data-index="${i}" aria-label="${esc(state.names[i]||('Deck '+(i+1)))}">${i+1}</button>`).join('')+(pg.count>1?arrow(1,'Next'):'')+`<button class="deck-tab deck-add" data-action="special-deck-add" aria-label="Add deck" ${state.decks.length>=D.MAX_DECKS?'disabled':''}>+</button>`;
 $('modeDeckGrid').style.setProperty('--mode-deck-size',state.size);$('modeDeckGrid').innerHTML=state.deck.map((id,i)=>modeDeckCard(id,i,state)).join('');decorateFormSlots($('modeDeckGrid'),specialMode);if(!$('modeDeckFormButton'))$('modeDeckTitle').parentElement.insertAdjacentHTML('beforeend','<button id="modeDeckFormButton" class="native-button purple" data-action="deck-forms">Heroes &amp; Evos</button>');$('modeDeckFormButton').dataset.mode=specialMode;$('modeDeckBattle').disabled=!state.valid;document.querySelector('.mode-deck-remove').disabled=state.decks.length<=1;
 const q=specialQuery.trim().toLowerCase(),eligible=state.eligible.map(id=>C.CARD_BY_ID[id]).filter(c=>!q||c.name.toLowerCase().includes(q));$('modeDeckCollection').innerHTML=eligible.map(c=>modeCollectionCard(c.id,state)).join('')||'<p class="empty-copy">No matching eligible cards.</p>';$('modeDeckCollectionNote').textContent=`${state.eligible.length} eligible cards · ${state.names[state.active]||('Deck '+(state.active+1))}${state.duplicates?' · Duplicate cards enabled for practice':''}`;hydrate($('modeDeck'));
}
$('modeDeckSearch').addEventListener('input',e=>{specialQuery=e.target.value;renderSpecialDeckScreen();});
$('modeDeckName').addEventListener('change',e=>{const st=D.modeState(profile,specialMode),r=D.modeRename(profile,specialMode,st.active,e.target.value);if(r.ok){profile=r.profile;save();renderSpecialDeckScreen();}});
$('modeDeckName').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.target.blur();}});
function specialDeckPool(state){return state.eligible.map(id=>C.CARD_BY_ID[id]).filter(c=>c.name.toLowerCase().includes(specialQuery.toLowerCase())).map(c=>modeCollectionCard(c.id,state)).join('')||'<p class="center">No eligible cards found.</p>';}

function fourCardBuilder(){
 const deck=profile.fourCardDeck,scroll=document.querySelector('.four-card-pool')?.scrollTop||0;
 panel('four-card-builder','4 Card Deck',`<div class="four-card-builder"><p class="center">Select a slot, then a card. Your four-card deck saves automatically.</p><div class="four-card-slots">${deck.map((id,i)=>`<button class="four-card-slot ${i===fourCardSlot?'selected':''}" data-action="four-card-slot" data-index="${i}" aria-label="Slot ${i+1}: ${esc(C.CARD_BY_ID[id].name)}" aria-pressed="${i===fourCardSlot}">${cardVisual(id)}<span class="cost">${C.CARD_BY_ID[id].cost}</span><b>${i+1}</b></button>`).join('')}</div><div class="four-card-controls"><span>Average elixir: ${(deck.reduce((n,id)=>n+C.CARD_BY_ID[id].cost,0)/4).toFixed(1)}</span>${button('Play','four-card-play','gold')}</div><input id="fourCardSearch" class="input" aria-label="Search four-card collection" placeholder="Search your cards" value="${esc(fourCardQuery)}"><div class="four-card-pool">${fourCardPoolMarkup()}</div><p class="small">Both players have four cards, at level 9. Played cards return after the normal cooldown. Your Trophy Road decks are unchanged.</p></div>`);
 document.querySelector('.four-card-pool').scrollTop=scroll;
 $('fourCardSearch').addEventListener('input',e=>{fourCardQuery=e.target.value;const pool=document.querySelector('.four-card-pool');pool.innerHTML=fourCardPoolMarkup();hydrate(pool);});
}
function fourCardPoolMarkup(){return C.CARDS.filter(c=>c.name.toLowerCase().includes(fourCardQuery.toLowerCase())).map(c=>`<button class="four-card-pick ${!profile.cheats.duplicates&&profile.fourCardDeck.includes(c.id)?'in-deck':''}" data-action="four-card-pick" data-id="${c.id}" aria-label="Use ${esc(c.name)}">${cardVisual(c.id)}<span class="cost">${c.cost}</span><small>${esc(c.name)}</small></button>`).join('')||'<p>No matching unlocked cards.</p>';}

function log(){social.log();}
function arenas(){road();}
let crownPage=null;
function renderCrownRoad(preserve=false){const P=RoyaleCrownRoad,c=P.progress(profile),target=c.nextUnclaimed||Math.max(1,c.milestones+1),page=crownPage===null?Math.floor((target-1)/25):crownPage,start=page*25+1,end=Math.min(start+24,999999),sc=$('crownRoadScroll'),old=sc.scrollTop;
 $('crownRoadLevel').textContent='Level '+fmt(c.crownLevel);$('crownRoadProgress').innerHTML=`<strong>${fmt(c.lifetimeCrowns)} lifetime crowns</strong><span>${c.remainder}/10 to next level · ${fmt(c.unclaimed)} unclaimed</span><div class="crown-progress-track"><i style="width:${c.remainder*10}%"></i></div>`;
 $('crownRoadPaging').innerHTML=`<button data-action="crown-page" data-page="${page-1}" ${page<=0?'disabled':''}>‹ Earlier</button><button data-action="crown-current">Your progress</button><button data-action="crown-page" data-page="${page+1}" ${end>=999999?'disabled':''}>Later ›</button>`;
 sc.innerHTML=`<p class="crown-road-intro">Every 10 crowns unlocks a new level. Rewards grow with every level; milestone rewards grow even faster. King Tower strength still uses King Level.</p><div class="crown-road-track">${Array.from({length:end-start+1},(_,i)=>{const n=start+i,r=E.crownReward(profile,n),state=P.state(profile,n),items=[{key:'gold',label:fmt(r.gold)+' Gold'},...r.gems?[{key:'gems',label:fmt(r.gems)+' Gems'}]:[],...Object.entries(r.wildcards).map(([k,v])=>({key:'road-wild-'+k.toLowerCase(),label:fmt(v)+' '+k+' Wild Cards'})),...r.chestKind?[{key:E.chestIcon(r.chestKind),label:({treasure:'Treasure',magic:'Magical',giant:'Giant',legendary:'Legendary'}[r.chestKind]||r.chestKind)+' Chest included'}]:[],...Object.entries(r.magicItems).map(([id,count])=>({key:U.magicItems.find(x=>x.id===id)?.icon||'gold',label:count+' '+(U.magicItems.find(x=>x.id===id)?.name||id)}))];return `<article class="crown-road-step ${state} ${n%5===0?'milestone':''}" data-crown-milestone="${n}"><div class="crown-road-marker">${icon('classic-crown')}<b>${n+1}</b></div><section class="crown-road-reward"><header><h2>Level ${fmt(n+1)}</h2><span>${fmt(n*10)} crowns</span></header><div class="crown-road-items">${items.map(item=>`<div>${icon(item.key)}<span>${esc(item.label)}</span></div>`).join('')}${contentRewardMarkup(r,{compact:true})}</div><button class="native-button ${state==='available'?'gold':'blue'}" data-action="crown-claim" data-milestone="${n}" ${state!=='available'?'disabled':''}>${state==='claimed'?'Collected':state==='available'?'Collect':'Locked'}</button></section></article>`;}).join('')}</div>`;
 hydrate($('crownRoad'));if(preserve)sc.scrollTop=old;else{sc.scrollTop=0;requestAnimationFrame(()=>{const at=sc.querySelector('[data-crown-milestone="'+target+'"]');if(at)sc.scrollTop=at.offsetTop-sc.offsetTop-16;});}}
function road(preserve=false){const previous=$('roadScroll').scrollTop;show('trophyRoad');$('roadTrophies').textContent=fmt(profile.trophies);const entries=[...R.ARENAS,...R.LEAGUES],current=R.currentProgression(profile),currentKey=current.id||current.name,peak=profile.highestTrophies;let nearest=null,nearestDiff=Infinity;for(const r of R.ROAD_REWARDS){if(Math.abs(profile.trophies-r.trophies)<nearestDiff){nearest=r;nearestDiff=Math.abs(profile.trophies-r.trophies);}}
 $('roadScroll').innerHTML=entries.map((a,i)=>({a,upper:entries[i+1]?.trophies||R.MAX_TROPHIES+1})).reverse().map(({a,upper})=>{const unlocks=a.number?R.arenaUnlocks(C.CARDS,C.DATA.arenas,a.number):[],steps=R.ROAD_REWARDS.filter(r=>r.trophies>=a.trophies&&r.trophies<upper).slice().reverse();const platform=({1:17,2:32,3:37,4:44,5:51,6:58,7:67,8:73,9:79,10:88,11:93,12:98,13:67,14:93})[a.number]??106;
 const tiles=steps.map((r,j)=>{const state=R.rewardState(profile,r),at=nearest?.id===r.id;return `<div class="road-step ${state} ${at?'player-step':''}" data-step-id="${r.id}" data-trophies="${r.trophies}"><span class="road-tick">${fmt(r.trophies)}</span>${at?`<div class="road-player-marker" aria-label="Your trophies: ${profile.trophies}">${icon('trophy')}<b>${fmt(profile.trophies)}</b></div>`:''}<div class="step-connector"></div><div class="step-ground" style="background-image:var(--ui-classic-platform-${a.number===1?[17,18,27,30,31][j%5]:a.number===2?[32,33,34,35,36][j%5]:platform})"></div><button class="road-reward reward-${r.align} ${state}" data-action="road-reward" data-id="${r.id}" aria-label="${esc(roadLabel(r)+' at '+r.trophies+' trophies, '+state)}"><span class="road-reward-art">${roadArt(r)}</span><b class="road-amount">${r.kind==='choice'||r.kind==='cards'||r.kind==='wildcards'||r.kind==='magic-item'?'×':''}${r.kind==='emote'?'Emote':r.kind==='chest'?'Chest':fmt(r.amount)}</b><span class="reward-state">${state==='claimed'?'✓':state==='available'?'Collect':'Locked'}</span>${state==='locked'?icon('classic-road-lock','reward-lock'):''}</button></div>`;}).join('');
 return `<section class="road-stop ${a.number?'':'road-league'} ${currentKey===(a.id||a.name)?'current':''}" data-road-id="${esc(a.id||a.name)}">${tiles}<div class="road-gate"><h2>${esc(a.name)}</h2><div class="road-title-strip"><b>${a.number?'Arena '+a.number:'League '+(R.LEAGUES.findIndex(x=>x.name===a.name)+1)}</b><b>${fmt(a.trophies)}</b></div><div class="road-unlocks ${peak<a.trophies?'locked':''}">${unlocks.length?'<small>Card unlocks</small><div>'+unlocks.map(c=>`<button data-action="card" data-id="${c.id}" aria-label="${esc(c.name)}">${cardVisual(c.id)}</button>`).join('')+'</div>':''}</div><button class="road-arena-info" data-action="arena-info" data-id="${a.id||''}" ${a.number?'':'disabled'} aria-label="${esc(a.name)} information">${icon(a.image)}<span>${currentKey===(a.id||a.name)?(a.number?'Your arena':'Your league'):peak>=a.trophies?'Reached':'Unlocks at '+fmt(a.trophies)}</span></button></div></section>`;}).join('')+`<div class="road-start-note">Win battles to climb. Rewards can be collected once per save.</div>`;
 const nextGate=[...R.ARENAS,...R.LEAGUES].find(a=>a.trophies>profile.trophies),lower=[...R.ARENAS,...R.LEAGUES].filter(a=>a.trophies<=profile.trophies).at(-1),progress=nextGate?Math.max(0,Math.min(100,(profile.trophies-(lower?.trophies||0))/(nextGate.trophies-(lower?.trophies||0))*100)):100,available=R.ROAD_REWARDS.filter(r=>R.rewardState(profile,r)==='available').length;
 $('roadProgress').innerHTML=`<div><b>${esc(lower?.name||current.name)}</b><span>${nextGate?fmt(nextGate.trophies-profile.trophies)+' to '+esc(nextGate.name):'Trophy Road complete'}</span></div><div class="road-progress-track"><i style="width:${progress}%"></i></div><nav><button data-action="road-my-progress">My trophies</button><button data-action="road-next-reward" ${available?'':'disabled'}>Collect rewards <b>${available}</b></button><select id="roadArenaJump" aria-label="View an arena on Trophy Road"><option value="">View arena / league</option>${entries.map(a=>`<option value="${esc(a.id||a.name)}">${esc(a.name)}</option>`).join('')}</select></nav>`;
 $('roadArenaJump').onchange=e=>{const el=$('roadScroll').querySelector('[data-road-id="'+CSS.escape(e.target.value)+'"] .road-gate');if(el)$('roadScroll').scrollTop+=el.getBoundingClientRect().top-$('roadScroll').getBoundingClientRect().top-25;};
 hydrate($('trophyRoad'));requestAnimationFrame(()=>{if(preserve){$('roadScroll').scrollTop=previous;return;}const at=$('roadScroll').querySelector('.player-step')||$('roadScroll').querySelector('[data-road-id="'+currentKey+'"]');if(at)$('roadScroll').scrollTop+=at.getBoundingClientRect().top-$('roadScroll').getBoundingClientRect().top-260;});}
function roadLabel(r){if(r.kind==='mystery-box')return modernLabel(r.box);if(r.kind==='consumable')return modernLabel(r.item);if(r.kind==='evo-shards')return 'Wild Evolution Shards';if(r.kind==='tower-troop')return 'Tower Troops';if(r.kind==='card')return C.CARD_BY_ID[r.cards[0]]?.name||'Cards';if(r.kind==='magic-item')return U.magicItems.find(i=>i.id===r.item)?.name||'Magic Item';if(r.kind==='chest')return ({'road-chest-legendarykings':'Legendary King’s Chest','road-chest-legendary':'Legendary Chest','road-chest-epic':'Epic Chest','road-chest-giant':'Giant Chest','road-chest-lightning':'Lightning Chest','magic-chest':'Magical Chest','silver-chest':'Silver Chest','gold-chest':'Golden Chest'})[R.rewardIcon(r)];return r.kind==='choice'?'Choose '+r.amount+' cards':r.kind==='wildcards'?r.rarity+' Wild Cards':r.kind==='tokens'?r.rarity+' Trade Token':r.kind==='cards'?r.rarity+' Cards':r.kind==='emote'?'Emote':r.kind==='gold'?'Gold':'Gems';}
function roadArt(r){if(r.kind==='card')return `<img data-card-image="${r.cards[0]}" alt="${esc(roadLabel(r))}">`;if(r.kind==='choice')return E.roadChoices(profile,r).map(id=>`<img data-card-image="${id}" alt="${esc(C.CARD_BY_ID[id].name)}">`).join('');return icon(R.rewardIcon(r));}
function roadReward(id){const r=R.ROAD_REWARDS.find(r=>r.id===id);if(!r)return;const state=R.rewardState(profile,r);if(state==='claimed'){toast('Reward already collected');return;}let body=`<div class="road-modal-art">${roadArt(r)}</div><p class="center">${fmt(r.amount)} ${esc(roadLabel(r))}</p>`;if(state==='locked')body+=`<p class="notice">Reach ${fmt(r.trophies)} trophies to collect this reward.</p>`;else if(r.kind==='choice')body+=`<p class="center">Choose one reward</p><div class="road-choice">${E.roadChoices(profile,r).map(id=>`<button class="native-button green" data-action="claim-road" data-id="${r.id}" data-card="${id}">${esc(C.CARD_BY_ID[id].name)}</button>`).join('')}</div>`;else if(r.kind==='tower-troop'&&r.supportCardAlt)body+=`<p>Choose a Tower Troop</p><div class="road-choice">${[r.supportCard,r.supportCardAlt].map(id=>button(esc(modernLabel(id)),'claim-road','green',`data-id="${r.id}" data-card="${id}"`)).join('')}</div>`;else body+=button('Collect','claim-road','green',`data-id="${r.id}"`);panel('road-reward',roadLabel(r),body);}
function roadInventory(){panel('road-inventory','Reward Inventory',`<p class="small">Wild cards can be applied to a card from an arena you have reached. Trade tokens are stored locally; live trading is not connected.</p>${['Common','Rare','Epic','Legendary','Champion'].map(r=>`<div class="checkline"><b>${r}</b><span>${profile.wildcards[r]} wild cards · ${profile.tradeTokens[r]} tokens</span></div>`).join('')}<label>Card<select id="wildcardCard" class="input">${E.cardPool(profile).map(c=>`<option value="${c.id}">${esc(c.name)} (${c.rarity})</option>`).join('')}</select></label><label>Amount<input id="wildcardCount" class="input" type="number" min="1" max="100000" value="1"></label>${button('Apply Wild Cards','use-wildcards','green')}`);}
function arenaInfo(id){const a=R.ARENAS.find(a=>a.id===id);if(!a)return;panel('arena-info',a.name,`<div class="arena-info-art">${icon(a.image)}</div><p class="center">Arena ${a.number} · ${fmt(a.trophies)} trophies</p><p class="notice">${a.id===profile.arena?'This is your current battle arena.':profile.highestTrophies>=a.trophies?'You have passed this arena. Battles use your current arena.':'Keep climbing Trophy Road to unlock this arena.'}</p>`);}

function cheatsMenu(){panel('cheats','Practice Cheats',`<p class="small">Local practice only. Matches with any cheat enabled do not earn trophies, gold or chests.</p>${[['duplicates','Duplicate cards in decks'],['placement','Place cards anywhere'],['overlevels','Card levels above 16'],['elixir','Always 10 elixir']].map(([key,label])=>`<label class="checkline"><span>${label}</span><input type="checkbox" data-cheat="${key}" ${profile.cheats[key]?'checked':''}></label>`).join('')}<div class="cheat-level-editor"><label>Card<select class="input" id="cheatCard">${C.CARDS.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Practice level<input class="input" id="cheatLevel" type="number" min="1" max="30" value="20"></label>${button('Set Level','cheat-level','green')}</div><p class="small">Levels 17–30 use extrapolated practice scaling. Enabling overlevels takes precedence over tournament-level mode. Switching duplicate cards off restores legal decks.</p>${button('Disable All Cheats','cheats-off','blue')}`);for(const el of $('modalPanel').querySelectorAll('[data-cheat]'))el.addEventListener('change',()=>{profile.cheats[el.dataset.cheat]=el.checked;profile=C.normalizeProfile(profile);save();renderCards();toast('Applies to the next battle');});}
function classicChest(crown=false){const result=E.classicChest(profile,crown),title=crown?'Crown Chest':'Free Chest';if(result.ok){chestRewards(result,crown?'crown':'wood',title);return;}const now=Date.now();panel('classic-chest',title,`<div class="reward-chest">${icon(crown?'classic-crown-chest':'classic-wood-chest')}</div><p class="center">${crown&&now>=profile.crownChestAt?'Earn 10 crowns in regular battles.':'Next in '+R.timeLabel(((crown?profile.crownChestAt:profile.freeChestAt)-now)/1000)}</p><p class="small center">Card pool: Arena ${R.currentArena(profile).number} and below.</p>`);}
function profileMenu(){panel('profile','Player Profile',`<div class="profile-badge">${icon('clan-badge')}<h3>${esc(profile.name)}</h3><p>${esc(profile.clan?.name||'No clan')} · Level ${profile.level}</p></div><div class="stats-grid">${[['Trophies',fmt(profile.trophies)],['Wins',profile.wins],['Battles',profile.matches],['Cards Found',profile.unlockedCards.length+' / '+C.CARDS.length],['Crowns',profile.earnedCrowns],['Donations',profile.clan?.donations||0]].map(([k,v])=>`<div class="stat-box">${k}<b>${v}</b></div>`).join('')}</div>${button('Battle Log','log','blue')}${button('Change Name','rename','blue')}`);}

async function changePotato(){
 if(preparing)return;const before=profile.graphics,enabled=!before.potato;profile.graphics=RoyaleGraphics.normalize({...before,potato:enabled});RoyaleGraphics.apply(profile.graphics);view.classList.toggle('potato-mode',enabled);native.releaseArenaCache?.();RoyaleCustomArena.clear();lastHomePaint=-Infinity;save();
 const active=battle;try{if(active){preparing=true;await native.prepareBattle(active,C.DATA);if(battle===active){signature='';refreshHand(true);}}else{header();if(screen==='cards')renderCards();else if(screen==='shop')renderShop();}}
 catch(e){profile.graphics=before;RoyaleGraphics.apply(before);view.classList.toggle('potato-mode',!!before.potato);save();toast('Graphics could not load: '+e.message);}
 finally{preparing=false;hydrate();settings();}
}

function settings(){panel('settings','Settings',`<div class="settings-body"><section class="settings-section"><h3>Battle Rules</h3><div class="checkline"><span>Trophy Road<small>Cards and King Tower</small></span><b>Collection levels</b></div><div class="checkline"><span>Other modes<small>Challenges, Training, 2v2, Friendly and War</small></span><b>Level 11</b></div><div class="checkline"><span>Opponent difficulty<small>Expert, with occasional short Hard streaks</small></span><b>Automatic</b></div><div class="checkline"><span>Placement previews</span><b class="setting-on-label">Always on</b></div><div class="checkline swarm-level-setting"><span>Compact swarm levels<small id="swarmLevelsHelp">Off shows a level above every bat, minion, skeleton, goblin and other troop.</small></span><button class="setting-switch ${profile.compactSwarmLevels?'on':''}" data-action="compact-swarm-levels" role="switch" aria-label="Compact swarm levels" aria-describedby="swarmLevelsHelp" aria-checked="${profile.compactSwarmLevels}">${profile.compactSwarmLevels?'On':'Off'}</button></div><div class="checkline"><span>AI reward learning<small>Legal matches only; cheats and replays excluded</small></span><b class="setting-on-label">Always on</b></div></section><section class="settings-section graphics-settings"><h3>Graphics</h3><div class="checkline potato-setting"><span>Potato Mode<small>Simple shapes, low-resolution art, no decorative effects</small></span><button class="setting-switch ${profile.graphics.potato?'on':''}" data-action="potato-toggle" role="switch" aria-checked="${profile.graphics.potato===true}">${profile.graphics.potato?'On':'Off'}</button></div>${[['textures','Textures'],['animations','Animations'],['particles','Particles'],['arenaBackgrounds','Arena backgrounds']].map(([key,label])=>`<label class="checkline"><span>${label}</span><select class="input graphics-select" data-graphics="${key}" aria-label="${label}">${RoyaleGraphics.OPTIONS[key].map(value=>`<option value="${value}" ${profile.graphics[key]===value?'selected':''}>${graphicsLabel(key,value)}</option>`).join('')}</select></label>`).join('')}<p class="small">Changes apply immediately and are saved. High and Max smooth artwork while preserving source detail. Ultra adds enhanced lighting and sharpness. Lower settings reduce graphics work.</p></section><section class="settings-section"><h3>Sound & display</h3><div class="checkline"><span>Sound effects</span><button class="setting-switch ${profile.sound?'on':''}" data-action="sound" role="switch" aria-checked="${profile.sound}">${profile.sound?'On':'Off'}</button></div><label class="checkline"><span>Volume <b id="volumeValue">${profile.volume}%</b></span><input type="range" min="0" max="100" step="5" id="settingsVolume" value="${profile.volume}" aria-label="Sound volume"></label><div class="settings-actions">${button('Fullscreen','fullscreen','blue')}${button('Controls','help','blue')}</div></section><section class="settings-section"><h3>AI data</h3><p class="settings-storage">${esc(learningStore.mode)}${learningStore.path?`<code>${esc(learningStore.path)}</code>`:'<small>Use the offline opener for AppData storage.</small>'}</p><div class="settings-actions">${button('Learning Center','learning-center','blue')}${button('Practice Cheats','cheats','green')}</div></section><section class="settings-section"><h3>Player save</h3><p class="small"><b>Local guest save</b><br>${storageOK?'Saved in this browser.':'Session only: browser storage is blocked.'} Export before changing sites. The world contains 4,000,000 simulated identities and 50,000 clans, generated locally. None are live human accounts.</p><div class="settings-actions">${button('Export Save','export-save','blue')}${button('Import Save','import-save','blue')}</div><button class="reset-data-link" data-action="reset">Reset practice progress</button></section><p class="settings-version">Web Royale ${B.version} · Original ${C.DATA.snapshot} data</p></div>`);
 for(const select of $('modalPanel').querySelectorAll('[data-graphics]'))select.addEventListener('change',()=>{profile.graphics=RoyaleGraphics.normalize({...profile.graphics,[select.dataset.graphics]:select.value});RoyaleGraphics.apply(profile.graphics);native.releaseArenaCache?.();RoyaleCustomArena.clear();native.towerShadowCache?.clear();lastHomePaint=-Infinity;save();});
 $('settingsVolume').addEventListener('input',e=>{profile.volume=Number(e.target.value);$('volumeValue').textContent=profile.volume+'%';save();});}
function help(){panel('help','Controls & Build Info',`<p><b>Select a card, then click the arena</b>, or drag it into position. Troops move and attack automatically.</p><div class="notice"><b>1–4</b> Select card &nbsp; <b>P</b> Pause<br><b>F</b> Fullscreen &nbsp; <b>Esc</b> Cancel / close</div><p class="small">Original UI graphics, ${C.CARDS.length} card portraits, original troop animations and models, and ${R.ARENAS.length} arenas plus Training Camp are bundled from your uploads. Runtime assets are served by this website; no external game-asset host is used.</p><p class="small">Card numbers and rule fields use snapshot <b>${C.DATA.snapshot}</b> from your supplied Clash Royale package. Movement, targeting, and abilities run in this browser's own interpreter, not the original native engine. Exact engine parity has not been established.</p><p class="small">Menus are functional local counterparts. Clan members, shop purchases, reward progression, and events are practice-only. Battle chests unlock with wins; reward quantities are local configuration. No real payment or Supercell account is involved.</p><p class="small">Menu and battle text use rasterized original game lettering. Unsupported characters use a readable system fallback. Optional UI, deployment and result sound cues come from your supplied APK. Version ${B.version}.</p>${button('Done','close','green')}`);}
function menu(){panel('menu','Menu',`${button('Settings','settings','blue')}${button('Battle Log','log','blue')}${button('Player Profile','profile','blue')}${button('Learning Center','learning-center','blue')}${button('Crown Rewards','pass-rewards','blue')}`);}


function towerTroops(){panel('tower-troops','Tower Troops',`<p class="small">Your Tower Troop defends the two Princess Tower positions and has its own card level. It is separate from your eight battle cards. Upgrades are capped by your Tower Power.</p><div class="tower-troop-inventory">${TT.catalog.map(c=>{const q=TT.quote(profile,c.id),up=TT.upgradeQuote(profile,c.id),selected=profile.selectedTowerTroop===c.id;return `<article class="tower-troop-card" data-tower-troop="${c.id}"><div class="tower-troop-art">${towerTroopVisual(c.id)}</div><h3>${esc(c.name)}</h3><p>${esc(c.rarity)} · Level ${q.level}</p><p>${up.haveCopies} / ${up.copies} cards · Tower Power cap ${up.levelCap}</p><small>${esc(q.supported?(q.unlocked?'':q.reason):'Not available in battle yet')}</small>${button(selected?'Selected':!q.supported?'Unavailable':!q.unlocked?'Locked':'Use','select-tower-troop','blue',`data-id="${c.id}" ${selected||!q.canUse?'disabled':''}`)}${button(up.level>=up.maxLevel?'Max Level':'Upgrade · '+fmt(up.gold)+' Gold','upgrade-tower-troop','gold',`data-id="${c.id}" data-level="${up.level}" ${!up.canUpgrade?'disabled':''}`)}${up.reason?`<small>${esc(up.reason)}</small>`:''}</article>`;}).join('')}</div>`);}

function modernLabel(id){return C.DATA.modernProgression.labels[id]||String(id).replace(/_/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2');}
// Deck form presentation
const FormUI=(()=>{
 const clean=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const names={evolution:'Evolution',hero:'Hero',wild:'Wild'};
 function slot(state,cardName='',form=null){
  const title=names[state.kind]||'Card',gate=state.unlockArena||[3,5,10][state.index],detail=!state.available?'Arena '+gate:state.status==='invalid'?'Choose a form':form?(form.kind==='evolution'?'Evolution':form.kind==='hero'?'Hero':'Champion'):'No form selected';
  return{className:`special-slot slot-${state.kind} slot-${state.status}`,label:`${title} slot ${state.index+1}${!state.available?', unlocks at Arena '+gate:''}. ${cardName}${form?', '+form.name:', no form selected'}`,markup:`<span class="slot-caption"><span class="slot-symbol ${state.kind}" aria-hidden="true">${state.kind==='evolution'?'◆':state.kind==='hero'?'♛':'◆♛'}</span><b>${title}</b><small>${clean(detail)}</small></span>`};
 }
 function inventory(form,quote,supported){
  const hero=form.kind==='hero',owned=quote.owned,ready=hero?quote.canUnlock:quote.canApplyWild;
  return{action:hero?'choose-hero':'apply-form-shard',disabled:owned||!supported||!ready,label:owned?'Unlocked':!supported?'Unavailable':hero?'Choose · '+quote.required+' Coins':'Use 1 Wild Shard',progress:owned?'Unlocked':hero?quote.amount+' / '+quote.required+' Hero Coins':quote.amount+' / '+quote.required+' Shards'};
 }
 return{slot,inventory};
})();
// End deck form presentation
function formContext(mode='ranked'){return{arena:R.highestArena(profile).number,casual:mode!=='ranked',unlockedForms:profile.unlockedForms,positionalSlots:true};}
function formDeckState(mode='ranked'){
 const set=mode==='ranked'?{decks:profile.decks,active:profile.activeDeck}:profile.modeDeckSets[mode];if(!set)return null;
 const deck=set.decks[set.active],forms=(mode==='ranked'?profile.deckForms.ranked:profile.deckForms.modes[mode])[set.active]||[];
 return{deck,forms,context:formContext(mode),slots:RoyaleCardForms.slotStates(deck,forms,formContext(mode),F)};
}
function formSupported(form){return RoyaleCardForms.formCapability(form.id,F).ok;}
function formBadge(id,card){const f=F.get(id);if(!f)return '';const type=f.kind==='evolution'?'Evolution':f.kind==='hero'?'Hero':'Champion',rarity=C.CARD_BY_ID[f.baseCardId]?.rarity,legendary=rarity==='Legendary',state=card?.formId===id?'active':card||profile.unlockedForms.includes(id)?'unlocked':'locked',key=f.kind==='champion'?'card-icon-champion':'card-icon-'+f.kind+(legendary?'-legendary':'')+'-'+state;if(B.uiImages[key]){const frame=cardOutline(f.baseCardId,{formId:id,active:card?.formId===id}).frame,im=B.uiFrameMeta?.[key],fm=B.uiFrameMeta?.[frame];let style='';if(im?.nativeBounds&&fm?.nativeBounds){const [x,y,right,bottom]=im.nativeBounds,[fx,fy,fr,fb]=fm.nativeBounds;style=`left:${(x-fx)/(fr-fx)*100}%;top:${(y-fy)/(fb-fy)*100}%;width:${(right-x)/(fr-fx)*100}%;height:${(bottom-y)/(fb-fy)*100}%`;}return `<img class="card-type-icon" data-ui="${key}" style="${style}" alt="${type}" title="${esc(f.name)}">${card&&f.kind==='evolution'&&!card.formId?`<span class="form-cycle-count">${card.evolutionCharge}/${card.evolutionCycles}</span>`:''}`;}const text=f.kind==='evolution'?(card?.formId===f.id?'EVOLVED':card?`${card.evolutionCharge}/${card.evolutionCycles}`:'EVO'):type.toUpperCase();return `<span class="form-badge ${f.kind}" title="${esc(f.name)}">${text}</span>`;}
function ownedFormBadges(id){return F.forCard(id).filter(f=>f.kind!=='champion'&&profile.unlockedForms.includes(f.id)).map(f=>`<span class="owned-form-badge ${f.kind}" title="${esc(f.name)} unlocked" aria-label="${esc(f.name)} unlocked">${B.uiImages['card-icon-'+f.kind+(C.CARD_BY_ID[id]?.rarity==='Legendary'?'-legendary':'')+'-unlocked']?icon('card-icon-'+f.kind+(C.CARD_BY_ID[id]?.rarity==='Legendary'?'-legendary':'')+'-unlocked','',f.kind==='hero'?'Hero':'Evolution'):f.kind==='evolution'?'◆':'♛'}</span>`).join('');}
function decorateFormSlots(parent,mode='ranked'){
 const state=formDeckState(mode);if(!state)return;
 for(const [index,el]of [...parent.children].entries()){
  const selected=F.get(state.forms[index]),badge=formBadge(state.forms[index]);applyCardOutline(el.querySelector('.card-visual'),state.deck[index],{formId:selected?.id});if(badge)el.querySelector('.card-visual')?.insertAdjacentHTML('beforeend',badge);
  const slot=state.slots.find(s=>s.index===index);if(!slot)continue;const ui=FormUI.slot(slot,C.CARD_BY_ID[state.deck[index]]?.name,selected);
  el.classList.add(...ui.className.split(' '));el.dataset.formSlot=String(index);el.dataset.slotKind=slot.kind;el.dataset.slotStatus=slot.status;el.setAttribute('aria-label',ui.label+'. '+(el.getAttribute('aria-label')||''));el.insertAdjacentHTML('beforeend',ui.markup);
 }
}
function deckForms(mode='ranked',focusSlot=null){
 const state=formDeckState(mode);if(!state)return;
 const q=F.qualify(state.deck,state.forms,state.context);
 panel('deck-forms','Special Deck Slots',`<p class="small">The first three deck positions are Evolution, Hero and Wild. The Wild slot accepts an Evolution, Hero or Champion. Standard cards can use any position.</p><div class="form-deck-list positional-form-list">${state.slots.map(slot=>{
  const id=state.deck[slot.index],c=C.CARD_BY_ID[id],selected=F.get(state.forms[slot.index]),ui=FormUI.slot(slot,c?.name||'Empty',selected),eligible=RoyaleCardForms.eligibleForms(id,slot.index,state.context,F),choices=eligible.filter(formSupported);
  return `<section class="form-deck-row ${ui.className}" data-deck-form-slot="${slot.index}"><div class="form-slot-portrait">${c?cardVisual(id,formBadge(selected?.id),false,{formId:selected?.id}):'<span class="empty-form-card">+</span>'}${ui.markup}</div><label><strong>${slot.index+1}. ${slot.kind==='wild'?'Wild · Hero / Evo':slot.kind==='hero'?'Hero / Champion':'Evolution'}</strong><span>${esc(c?.name||'Empty slot')}</span><select class="input" data-form-choice="${slot.index}" aria-label="${esc(ui.label)}" ${!slot.available||!choices.length?'disabled':''}>${F.champion(id)?'':'<option value="">Standard</option>'}${eligible.map(f=>`<option value="${f.id}" ${selected?.id===f.id?'selected':''} ${!formSupported(f)?'disabled':''}>${esc(f.name)}${!formSupported(f)?' · Unavailable':''}</option>`).join('')}</select><small>${!slot.available?'Unlocks at Arena '+slot.unlockArena:!choices.length?'No unlocked form for this card':slot.kind==='wild'?'Choose either form above':'Choose an unlocked form above'}</small></label></section>`;
 }).join('')}</div>${q.errors.length?`<p class="notice">${esc(q.errors[0].reason)}</p>`:''}${!F.forms.length?'<p class="notice">This version has no Hero or Evolution cards configured. These slots are ready for future forms.</p>':''}${button('Hero & Evo Inventory','form-inventory','purple')}`);
 for(const select of $('modalPanel').querySelectorAll('[data-form-choice]'))select.addEventListener('change',()=>{
  const r=D.setForm(profile,{mode,slot:Number(select.dataset.formChoice),formId:select.value||null,...state.context});if(!r.ok)toast(r.reason);else{profile=r.profile;save();if(screen==='cards')renderCards();if(screen==='modeDeck')renderSpecialDeckScreen();}deckForms(mode,Number(select.dataset.formChoice));
 });
 if(focusSlot!==null)$('modalPanel').querySelector(`[data-form-choice="${focusSlot}"]`)?.focus();
}
function formInventory(kind='all'){
 const rows=F.forms.filter(f=>f.kind!=='champion'&&(kind==='all'||f.kind===kind));
 panel('form-inventory','Heroes & Evolutions',`<div class="form-currencies"><span><b data-form-currency="hero">${profile.heroCoins}</b> Hero Coins</span><span><b data-form-currency="wild">${profile.evoWildShards}</b> Wild Shards</span></div><nav class="form-inventory-tabs" aria-label="Form collection"><button data-action="form-inventory" data-kind="all" aria-pressed="${kind==='all'}">All</button><button data-action="form-inventory" data-kind="hero" aria-pressed="${kind==='hero'}">Heroes</button><button data-action="form-inventory" data-kind="evolution" aria-pressed="${kind==='evolution'}">Evolutions</button></nav><p class="small">Choose a Hero for 200 Hero Coins. Evolutions unlock automatically at six matching shards. Use Wild Shards one at a time on the Evolution you choose.</p>${rows.length?`<div class="form-inventory-grid">${rows.map(f=>{
  const q=MR.formQuote(profile,f.id,{registry:F}),supported=formSupported(f),a=FormUI.inventory(f,q,supported);
  return `<article class="form-inventory-card ${f.kind} ${q.owned?'form-owned':''}" data-form-id="${f.id}"><div>${cardVisual(f.baseCardId,formBadge(f.id),false,{formId:f.id})}</div><h3>${esc(f.name)}</h3><p class="form-unlock-progress" data-form-progress="${f.id}">${esc(a.progress)}</p><div class="form-shard-track" role="progressbar" aria-label="${esc(f.name)} unlock progress" aria-valuemin="0" aria-valuemax="${q.required}" aria-valuenow="${q.owned?q.required:Math.min(q.required,q.amount)}"><i style="width:${q.owned?100:Math.min(100,q.amount/q.required*100)}%"></i></div>${button(a.label,a.action,f.kind==='hero'?'gold':'purple',`data-id="${f.id}" ${a.disabled?'disabled':''}`)}${q.owned?button('Use '+(f.kind==='hero'?'Hero':'Evolution'),'use-form','blue',`data-id="${f.id}" ${!supported?'disabled':''}`):!supported?'<small>Not available in battle yet</small>':''}</article>`;
 }).join('')}</div>`:'<div class="empty-form-inventory"><span class="slot-symbol wild" aria-hidden="true">◆♛</span><h3>No forms configured</h3><p>The Evolution, Hero and Wild slots are available in the deck builder. This version has no Hero or Evolution cards to unlock.</p></div>'}`);
}
function formCardActions(id){const forms=F.forCard(id).filter(f=>f.kind!=='champion'&&profile.unlockedForms.includes(f.id));if(!forms.length)return '';return `<section class="card-form-actions" aria-label="Unlocked forms">${forms.map(f=>button('Use '+(f.kind==='hero'?'Hero':'Evolution'),'use-form','purple',`data-id="${f.id}" ${!formSupported(f)?'disabled':''}`)).join('')}${button('Hero & Evo Inventory','form-inventory','blue')}</section>`;}

function refreshAbilities(){
 let node=$('battleAbilities');if(!node){node=document.createElement('div');node.id='battleAbilities';node.setAttribute('aria-label','Hero and Champion abilities');$('battle').append(node);}if(!battle||battle.isReplay||battle.isSandbox){node.hidden=true;return;}
 const units=battle.units.filter(u=>u.owner===0&&battle.isPresent(u)&&!u.dead),rows=units.map(u=>({u,s:battle.abilityStatus(u.id)})).filter(x=>x.s);node.hidden=!rows.length;
 const html=rows.map(({u,s})=>{const f=F.get(s.formId),seconds=Math.max(0,Math.ceil(s.cooldownUntil-battle.time)),available=s.ready&&s.supported!==false&&battle.elixir[0]+1e-7>=s.cost,caption=s.supported===false?'Unavailable':s.pending?'Casting':seconds?seconds+'s':s.charges===0?'Used':s.cost+' Elixir';return `<button class="ability-button" data-action="battle-ability" data-entity="${u.id}" ${available?'':'disabled'} aria-label="${esc(f?.name||u.entity)} ability: ${caption}" title="${esc(s.supported===false?'This ability is not available yet.':f?.description||'')}"><img data-card-image="${f?.baseCardId||u.card||''}" alt=""><span><b>${esc(f?.name||u.entity)}</b><small>${caption}</small></span></button>`;}).join('');if(node._html!==html){node._html=html;node.innerHTML=html;hydrate(node);}
}

