// Generated RandomDeck loadout
let randomDeckPool=null;
function generatedRandomLoadout(seed,context={}){
 if(!randomDeckPool)randomDeckPool=C.CARDS.filter(c=>RoyaleModernActions.canDeployCard(null,c).ok);
 const cards=[...randomDeckPool],random=C.rng(seed);for(let i=cards.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]];}
 const originalDeck=[];let champions=0;for(const card of cards){if(F.champion(card.id)&&champions>=2)continue;if(F.champion(card.id))champions++;originalDeck.push(card.id);if(originalDeck.length===8)break;}
 if(originalDeck.length<8)return{ok:false,deck:originalDeck,forms:[],errors:[{reason:'This mode needs eight available cards'}]};
 const moved=F.migrateDeck(originalDeck,F.selections(originalDeck,[]),{...context,positionalSlots:true}),forms=[...moved.forms];
 for(let index=0;index<3;index++){if(forms[index])continue;const choices=RoyaleCardForms.eligibleForms(moved.deck[index],index,context,F).filter(f=>RoyaleCardForms.formCapability(f.id,F).ok),chosen=choices.find(f=>f.kind==='evolution')||choices[0];if(chosen)forms[index]=chosen.id;}
 const q=F.qualify(moved.deck,forms,{...context,positionalSlots:true});return{...moved,originalDeck,forms:q.forms,errors:q.errors,ok:q.ok};
}
// End generated RandomDeck loadout
