 const arenaId=RoyaleArenaSelection.choose({mode,queue,current:R.currentArena(profile).id,seed:matchSeed,requested:extra.arenaId});native.setArena(RoyaleArenaSelection.base(arenaId));
 const options={...extra,arenaId,queue,profile,brain:new RoyaleLearning.SharedBrain(model),learning:true,practice:extra.practice===true||training||['training','friendly','clan-war','self-play'].includes(queue),shuffleDeck:true,
  deck:extra.deck||modeDeck,enemyDeck:extra.enemyDeck||modeEnemyDeck,allyDeck:casual?RoyaleTrainingDecks.forMode(matchSeed+211,R.ARENAS.length,mode):ally.deck,enemyAllyDeck:casual?RoyaleTrainingDecks.forMode(matchSeed+401,R.ARENAS.length,mode):enemyAlly.deck,opponent,
  mode,seatLevels:[profile.cardLevels,opponent.levels,ally.levels,enemyAlly.levels],kingLevels:[profile.level,opponent.kingLevel,ally.kingLevel,enemyAlly.kingLevel],seed:matchSeed};
